/**
 * Data access for the Java Programming course. Loaders only — every rule lives in
 * `core/learning/jcourse.ts`, and every artifact is generated by `scripts/java-course.cjs`.
 *
 * The compiler call mirrors the C course's shape: the app's own proxy first (headers, budget), then
 * the keyless public Judge0 CE instance, so Run works on a static host and on a dev server with no
 * API route. It is a real javac compile on JDK 17 — never a simulated answer, and a failure to
 * reach it is reported as a failure.
 */
import { useEffect, useState } from 'react';
import type {
  JAssessmentSet, JCodingQuestion, JCourseFile, JDebugChallenge, JIndex, JInterviewItem, JLab, JProject,
} from '../learning/jcourse';

const cache = new Map<string, Promise<unknown>>();

function load<T>(file: string): Promise<T> {
  const key = file;
  if (!cache.has(key)) {
    cache.set(key, fetch(`generated/java-course/${file}`).then((r) => {
      if (!r.ok) throw new Error(`java-course/${file}: ${r.status}`);
      return r.json() as Promise<T>;
    }).catch((err) => { cache.delete(key); throw err; }));
  }
  return cache.get(key) as Promise<T>;
}

export function useJIndex(): JIndex | null {
  const [data, setData] = useState<JIndex | null>(null);
  useEffect(() => { let live = true; load<JIndex>('index.json').then((d) => live && setData(d)).catch(() => {}); return () => { live = false; }; }, []);
  return data;
}

