export interface JRunRequest {
  source: string;
  stdin?: string;
  args?: string;
  tests?: { name?: string; stdin?: string; stdout: string }[];
}
export interface JRunResult {
  status: string;
  stdout: string;
  stderr: string;
  compileOutput: string;
  exitCode: number | null;
  time: number | null;
  memory: number | null;
  timedOut: boolean;
  tests?: { name: string; pass: boolean; expected: string; actual: string }[];
  passed?: number;
  total?: number;
}

const PUBLIC_COMPILER = 'https://ce.judge0.com';
const JAVA_LANGUAGE_ID = 91; // Java (JDK 17.0.6)
const COMPILER_TIMEOUT_MS = 25_000;

function shapeRun(body: any, expected?: string): JRunResult & { pass?: boolean } {
  const stdout = String(body?.stdout ?? '');
  const stderr = String(body?.stderr ?? '');
  const compileOutput = String(body?.compile_output ?? '');
  const status = String(body?.status?.description ?? 'Unknown');
  const statusId = Number(body?.status?.id ?? 0);
  const ran = statusId === 3 || statusId === 4;
  const failed = Boolean(compileOutput.trim()) || !ran;
  return {
    status, stdout, stderr, compileOutput,
    exitCode: typeof body?.exit_code === 'number' ? body.exit_code : ran ? 0 : statusId ? 1 : null,
    time: body?.time ? Math.round(Number(body.time) * 1000) : null,
    memory: body?.memory ?? null,
    timedOut: /time limit/i.test(status),
    ...(expected === undefined ? {} : { pass: !failed && stdout.trim() === expected.trim(), expected }),
  };
}

async function judgeRun(source: string, stdin: string, args: string): Promise<any> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), COMPILER_TIMEOUT_MS);
  try {
    const res = await fetch(`${PUBLIC_COMPILER}/submissions?base64_encoded=false&wait=true`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        source_code: source,
        language_id: JAVA_LANGUAGE_ID,
        stdin,
        command_line_arguments: args,
      }),
      signal: controller.signal,
    });
    if (!res.ok) {
      throw new Error(res.status === 429
        ? 'The free Java compiler is busy right now. Try again in a few seconds.'
        : `The compiler service answered ${res.status}.`);
    }
    return await res.json();
  } catch (error) {
    if (error instanceof Error && error.name === 'AbortError') {
      throw new Error('The compiler took too long. Try a smaller program.');
    }
    throw error instanceof Error ? error : new Error('The Java compiler is unreachable right now.');
  } finally {
    clearTimeout(timer);
  }
}

async function runWithoutApi(req: JRunRequest): Promise<JRunResult> {
  const stdin = req.stdin ?? '';
  const args = req.args ?? '';
  const tests = req.tests ?? [];
  if (Array.isArray((req as { files?: unknown[] }).files) && (req as { files?: unknown[] }).files?.length) {
    throw new Error('Java Code Bro compiles one file. Keep every class in the same file.');
  }
  if (!tests.length) return shapeRun(await judgeRun(req.source, stdin, args));
  const results = [];
  for (const [i, test] of tests.entries()) {
    const shaped = shapeRun(await judgeRun(req.source, test.stdin ?? stdin, args), test.stdout);
    results.push({ name: test.name || `Test ${i + 1}`, pass: shaped.pass === true, expected: test.stdout, actual: shaped.stdout });
    // The free instance asks for a little breathing room between submissions.
    if (i < tests.length - 1) await new Promise((resolve) => setTimeout(resolve, 400));
  }
  const passed = results.filter((r) => r.pass).length;
  return {
    status: passed === results.length ? 'Accepted' : 'Wrong Answer',
    stdout: results.map((r) => r.actual).join('\n'), stderr: '', compileOutput: '',
    exitCode: passed === results.length ? 0 : 1, time: null, memory: null, timedOut: false,
    tests: results, passed, total: results.length,
  };
}

export async function runJava(req: JRunRequest): Promise<JRunResult> {
  const proxy = await fetch('api/java/execute', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(req),
  }).catch(() => null);
  if (proxy) {
    const raw = await proxy.text().catch(() => '');
    let body: any = null;
    try { body = JSON.parse(raw); } catch { body = null; }
    if (proxy.ok && body && typeof body.status === 'string') return body as JRunResult;
    const retryable = !proxy.ok && [401, 403, 404, 405, 408, 425, 500, 501, 502, 503, 504].includes(proxy.status);
    if (!retryable && !proxy.ok && body?.error) throw new Error(String(body.error));
  }
  return runWithoutApi(req);
}
